/// Bridges passive observable telemetry into the runner's shared StateHub.
pub struct StateHubTelemetrySink(StateHubSender);

impl StateHubTelemetrySink {
    /// Create a telemetry sink backed by a StateHub sender.
    pub fn new(sender: StateHubSender) -> Self {
        Self(sender)
    }
}

#[async_trait::async_trait]
impl TelemetryEventSink for StateHubTelemetrySink {
    async fn emit(
        &self,
        event: &ObservableEvent,
        ancestry: &[LensScope],
    ) -> roko_core::Result<Vec<Signal>> {
        let errors = self.0.emit_observable(event, ancestry);
        if errors.is_empty() {
            Ok(Vec::new())
        } else {
            Err(roko_core::RokoError::invalid(errors.join("; ")))
        }
    }
}

async fn emit_signal_scores(
    telemetry: &dyn TelemetryEventSink,
    plan_id: &str,
    task_id: &str,
    scores: &[ScoredSignalDiagnostic],
) -> usize {
    let ancestry = [
        LensScope::Cell(task_id.to_string()),
        LensScope::Graph(plan_id.to_string()),
    ];
    let mut seen = HashSet::new();
    let mut emitted = 0;
    for scored in scores {
        let Some(parsed_ref) = ContentHash::from_hex(&scored.signal_ref) else {
            continue;
        };
        let Ok(result) =
            serde_json::from_str::<roko_compose::CandidateScoreResult>(&scored.score_result)
        else {
            continue;
        };
        if parsed_ref.to_hex() != scored.signal_ref
            || !result.effective.is_finite()
            || !result.fallback.is_finite()
            || !result.final_score.is_finite()
            || !seen.insert(scored.signal_ref.as_str())
        {
            continue;
        }
        let event =
            ObservableEvent::SignalScored(scored.signal_ref.clone(), scored.score_result.clone());
        if let Err(error) = telemetry.emit(&event, &ancestry).await {
            warn!(%error, signal = %scored.signal_ref, "signal score telemetry delivery failed");
        }
        emitted += 1;
    }
    emitted
}

async fn emit_agent_budget_update(
    telemetry: &dyn TelemetryEventSink,
    agent_id: &str,
    plan_id: &str,
    task_id: &str,
    spent_usd: f64,
    budget_usd: f64,
) -> bool {
    if !spent_usd.is_finite() || spent_usd < 0.0 || !budget_usd.is_finite() || budget_usd <= 0.0 {
        return false;
    }
    let remaining_usd = (budget_usd - spent_usd).max(0.0);
    let event = ObservableEvent::AgentBudgetUpdate {
        agent: agent_id.to_string(),
        spent_usd,
        remaining_usd,
        vitality: (remaining_usd / budget_usd).clamp(0.0, 1.0),
    };
    let ancestry = [
        LensScope::Agent(agent_id.to_string()),
        LensScope::Cell(task_id.to_string()),
        LensScope::Graph(plan_id.to_string()),
    ];
    if let Err(error) = telemetry.emit(&event, &ancestry).await {
        warn!(%error, agent_id, "agent budget telemetry delivery failed");
    }
    true
}

async fn emit_memory_consolidated(
    telemetry: &dyn TelemetryEventSink,
    promoted: usize,
    demoted: usize,
    pruned: usize,
) {
    let event = ObservableEvent::MemoryConsolidated {
        promoted,
        demoted,
        pruned,
    };
    if let Err(error) = telemetry.emit(&event, &[LensScope::Global]).await {
        warn!(%error, "memory consolidation telemetry delivery failed");
    }
}

// ─── ContextScopingConfig ───────────────────────────────────────────────

/// Per-role limits on how much context is injected into agent prompts.
///
/// Different roles benefit from different context sizes. Implementers need
/// rich error patterns and fewer historical episodes (focused on the task at
/// hand). Reviewers benefit from more episodes to compare against but fewer
/// raw error patterns. Strategists work at plan-level and receive no
/// file-level context.
///
/// These limits are applied when assembling the prompt before agent dispatch.
/// They can be overridden via `[knowledge]` in `roko.toml`; if absent the
/// role-specific defaults below are used.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ContextScopingConfig {
    /// Max neuro/file-intelligence entries injected (0 = skip entirely).
    pub max_file_intel_entries: usize,
    /// Max warning entries injected (0 = skip entirely).
    pub max_warning_entries: usize,
    /// Max error-pattern entries injected (0 = skip entirely).
    pub max_error_patterns: usize,
    /// Max similar-episode entries injected (0 = skip entirely).
    pub max_similar_episodes: usize,
}

#[cfg(test)]
mod tests_extension_startup {
    use super::*;
    use roko_core::extension::{Extension, ExtensionLayer, ExtensionMeta, PackageTier};

    struct FailingInitExtension {
        meta: ExtensionMeta,
    }

    #[async_trait::async_trait]
    impl Extension for FailingInitExtension {
        fn name(&self) -> &str {
            &self.meta.name
        }

        fn layer(&self) -> ExtensionLayer {
            self.meta.layer
        }

        fn meta(&self) -> ExtensionMeta {
            self.meta.clone()
        }

        async fn on_init(
            &mut self,
        ) -> std::result::Result<(), Box<dyn std::error::Error + Send + Sync>> {
            Err("fixture init failure".into())
        }
    }

    fn failing_chain(
        optional: bool,
    ) -> Arc<tokio::sync::Mutex<roko_core::extension::ExtensionChain>> {
        let mut chain = roko_core::extension::ExtensionChain::new();
        chain.add(Box::new(FailingInitExtension {
            meta: ExtensionMeta {
                name: if optional { "optional" } else { "required" }.to_string(),
                layer: ExtensionLayer::Foundation,
                optional,
                depends_on: Vec::new(),
                soft_depends_on: Vec::new(),
                version: "1.0.0".to_string(),
                tier: PackageTier::NativeRust,
            },
        }));
        Arc::new(tokio::sync::Mutex::new(chain))
    }

    #[tokio::test]
    async fn runner_startup_rejects_required_extension_init_failure() {
        let chain = failing_chain(false);
        let error = initialize_extensions(Some(&chain)).await.unwrap_err();
        assert!(error.to_string().contains("required"));
        assert!(error.to_string().contains("fixture init failure"));
    }

    #[tokio::test]
    async fn runner_startup_isolates_optional_extension_init_failure() {
        let chain = failing_chain(true);
        initialize_extensions(Some(&chain)).await.unwrap();
        let chain = chain.lock().await;
        assert!(chain.statuses()[0].disabled);
    }
}

impl ContextScopingConfig {
    /// Role-specific preset for an **Implementer**: focused context, more
    /// error patterns, fewer historical episodes.
    pub const IMPLEMENTER: Self = Self {
        max_file_intel_entries: 10,
        max_warning_entries: 5,
        max_error_patterns: 5,
        max_similar_episodes: 3,
    };

    /// Role-specific preset for a **Reviewer** (Auditor / QuickReviewer /
    /// Critic): broader episode recall, fewer raw error patterns.
    pub const REVIEWER: Self = Self {
        max_file_intel_entries: 3,
        max_warning_entries: 3,
        max_error_patterns: 3,
        max_similar_episodes: 5,
    };

    /// Role-specific preset for a **Strategist** (Strategist / Architect /
    /// Conductor): plan-level view only — no file-level context injected.
    pub const STRATEGIST: Self = Self {
        max_file_intel_entries: 0,
        max_warning_entries: 0,
        max_error_patterns: 0,
        max_similar_episodes: 0,
    };
}

/// Return the [`ContextScopingConfig`] for the given agent role.
///
/// Maps each [`AgentRole`] to one of the three canonical presets
/// (`IMPLEMENTER`, `REVIEWER`, `STRATEGIST`).  Falls back to the
/// `IMPLEMENTER` preset for any role not explicitly listed.
///
/// This is the single wiring point: callers in the event loop call
/// `role_context_limits(role_enum)` before assembling context sections,
/// then use the returned limits to cap how many entries they inject.
pub(crate) fn role_context_limits(role: AgentRole) -> ContextScopingConfig {
    use roko_core::AgentRole as R;
    match role {
        // ── Strategist-class: plan-level only ──────────────────────────
        R::Strategist | R::Architect | R::Conductor | R::PlanLifecycleManager => {
            ContextScopingConfig::STRATEGIST
        }
        // ── Reviewer-class: broader episode recall ──────────────────────
        R::Auditor
        | R::QuickReviewer
        | R::Critic
        | R::SpecDriftDetector
        | R::RegressionDetector
        | R::DocVerifier
        | R::SnapshotComparator => ContextScopingConfig::REVIEWER,
        // ── Implementer-class (default): focused context ────────────────
        _ => ContextScopingConfig::IMPLEMENTER,
    }
}

