        let done = TaskAttemptRef::new("plan", "done", 1);
        let sibling = TaskAttemptRef::new("plan", "sibling", 1);
        let mut runtimes = HashMap::from([(done.key(), runtime.clone()), (sibling.key(), runtime)]);
