// ─── Provider rate-limit pool tests (E48-T03) ─────────────────────────────────
//
// Verify that a single `Arc<ProviderRateLimiter>` shared by `SharedAgentFactory`
// gates concurrent agent dispatches without false contention:
//
// 1. Concurrent acquires for the **same** provider share one RPM budget.
// 2. Concurrent acquires for **different** providers are independent.
//
// Both assertions confirm the pool is shared (not rebuilt per-task) because
// that is the invariant `SharedAgentFactory::new` establishes and
// `spawn_shared_agent_bridge` relies on.
#[cfg(test)]
mod tests_provider_rate_limit {
    use std::collections::HashMap;
    use std::sync::Arc;
    use std::time::{Duration, Instant};

    use roko_agent::rate_limit::{ProviderLimits, ProviderRateLimiter};

    /// Two concurrent `acquire` calls for the same provider share the
    /// single RPM budget slot via one Arc.
    ///
    /// At 600 RPM (10 req/s) both requests should complete within 500 ms on
    /// any realistic host, proving they are not blocked by a per-task rebuild.
    #[tokio::test]
    async fn provider_rate_limit_pool_shared_across_concurrent_dispatches() {
        let limiter = Arc::new(ProviderRateLimiter::new(600));
        let start = Instant::now();

        let l1 = Arc::clone(&limiter);
        let l2 = Arc::clone(&limiter);
        let ((), ()) = tokio::join!(async move { l1.acquire("anthropic").await }, async move {
            l2.acquire("anthropic").await
        },);

        assert!(
            start.elapsed() < Duration::from_millis(500),
            "shared pool should not stall under 600 RPM: {:?}",
            start.elapsed()
        );
    }

    /// Concurrent acquires for different providers must not contend with each
    /// other — each provider has an independent RPM budget in the shared pool.
    #[tokio::test]
    async fn provider_rate_limit_pool_independent_budgets_per_provider() {
        let mut limits = HashMap::new();
        limits.insert("anthropic".to_string(), ProviderLimits { rpm: 600, tpm: 0 });
        limits.insert(
            "openrouter".to_string(),
            ProviderLimits { rpm: 600, tpm: 0 },
        );
        let limiter = Arc::new(ProviderRateLimiter::with_provider_limits(60, limits));
        let start = Instant::now();

        let la = Arc::clone(&limiter);
        let lb = Arc::clone(&limiter);
        let ((), ()) = tokio::join!(async move { la.acquire("anthropic").await }, async move {
            lb.acquire("openrouter").await
        },);

        assert!(
            start.elapsed() < Duration::from_millis(500),
            "independent providers should not contend: {:?}",
            start.elapsed()
        );
    }

    /// Validate the `from_provider_configs` constructor path used by
    /// `SharedAgentFactory`: an Arc-shared limiter must not stall when 4
    /// concurrent tasks all acquire within a 600 RPM budget.
    #[tokio::test]
    async fn provider_rate_limit_pool_from_provider_configs_high_rpm() {
        // Mirror what SharedAgentFactory::new passes to from_provider_configs.
        let limiter = Arc::new(ProviderRateLimiter::new(600));
        let start = Instant::now();

        let handles: Vec<_> = (0..4)
            .map(|_| {
                let l = Arc::clone(&limiter);
                tokio::spawn(async move { l.acquire("anthropic").await })
            })
            .collect();

        for h in handles {
            h.await.expect("acquire task should not panic");
        }

        // 4 requests at 600 RPM should finish well within 2 s on any host.
        assert!(
            start.elapsed() < Duration::from_secs(2),
            "4 concurrent acquires at 600 RPM should not stall: {:?}",
            start.elapsed()
        );
    }
}

#[cfg(test)]
mod tests_error_pattern_sharing {
    //! Unit tests for E45-T03: error pattern sharing via discovered-patterns.json.
    //!
    //! Tests cover:
    //! - Pattern recording from gate output to the JSON store.
    //! - Deduplication by normalized key (same error code + file = same pattern).
    //! - Prompt section formatting from the loaded store.
    //! - Handling of missing or empty stores.

    use super::*;
    use roko_learn::error_pattern_store::ErrorPatternStore;
    use tempfile::TempDir;

    /// A cargo-json-format compile error line for `E0425` in `src/lib.rs`.
    const CARGO_E0425_LIB: &str = r#"{"reason":"compiler-message","message":{"message":"cannot find value `foo`","code":{"code":"E0425","explanation":null},"level":"error","spans":[{"file_name":"src/lib.rs","line_start":10,"column_start":3,"is_primary":true}],"children":[{"message":"maybe try import foo","level":"help"}]}}"#;

    /// The same error code but in `src/main.rs` -- different key, different pattern.
    const CARGO_E0425_MAIN: &str = r#"{"reason":"compiler-message","message":{"message":"cannot find value `foo`","code":{"code":"E0425","explanation":null},"level":"error","spans":[{"file_name":"src/main.rs","line_start":5,"column_start":1,"is_primary":true}],"children":[]}}"#;

    /// Repeated occurrence of `E0425` in `src/lib.rs` at a different line -- same key.
    const CARGO_E0425_LIB_LINE2: &str = r#"{"reason":"compiler-message","message":{"message":"cannot find value `bar`","code":{"code":"E0425","explanation":null},"level":"error","spans":[{"file_name":"src/lib.rs","line_start":99,"column_start":7,"is_primary":true}],"children":[]}}"#;

    // -- record_discovered_error_patterns ------------------------------------

    #[test]
    fn records_compile_error_to_discovered_patterns_json() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path().join("learn");

        record_discovered_error_patterns(
            &learn_dir,
            "compile:cargo",
            CARGO_E0425_LIB,
            "plan-1",
            "task-1",
        );

        let path = learn_dir.join("discovered-patterns.json");
        assert!(path.exists(), "discovered-patterns.json must be created");

        let store = ErrorPatternStore::load(&path);
        assert_eq!(store.len(), 1, "one distinct error code/file pair expected");
    }

    #[test]
    fn same_error_code_same_file_deduplicates_into_single_pattern() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path().join("learn");

        // Two calls with the same error code in the same file but different lines.
        record_discovered_error_patterns(
            &learn_dir,
            "compile:cargo",
            CARGO_E0425_LIB,
            "plan-1",
            "task-1",
        );
        record_discovered_error_patterns(
            &learn_dir,
            "compile:cargo",
            CARGO_E0425_LIB_LINE2,
            "plan-1",
            "task-2",
        );

        let path = learn_dir.join("discovered-patterns.json");
        let store = ErrorPatternStore::load(&path);

        // Key is `E0425::src/lib.rs` regardless of line number, so only one entry.
        assert_eq!(
            store.len(),
            1,
            "same error code + file must produce a single pattern entry"
        );
        let top = store.top_patterns(5);
        assert_eq!(
            top[0].occurrences, 2,
            "occurrence count must increment on second observation"
        );
    }

    #[test]
    fn different_files_produce_separate_patterns() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path().join("learn");

        record_discovered_error_patterns(
            &learn_dir,
            "compile:cargo",
            CARGO_E0425_LIB,
            "plan-1",
            "task-1",
        );
        record_discovered_error_patterns(
            &learn_dir,
            "compile:cargo",
            CARGO_E0425_MAIN,
            "plan-1",
            "task-2",
        );

        let path = learn_dir.join("discovered-patterns.json");
        let store = ErrorPatternStore::load(&path);

        // `E0425::src/lib.rs` vs `E0425::src/main.rs` are distinct keys.
        assert_eq!(
            store.len(),
            2,
            "errors in different files must produce separate pattern entries"
        );
    }

    #[test]
    fn non_fatal_on_empty_gate_output() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path().join("learn");

        // Should not panic or create a file when there are no classifiable errors.
        record_discovered_error_patterns(&learn_dir, "compile:cargo", "", "plan-1", "task-1");

        let path = learn_dir.join("discovered-patterns.json");
        // File may or may not be written -- we only care there is no panic.
        let _ = path.exists();
    }

    // -- format_discovered_patterns_section ----------------------------------

    #[test]
    fn returns_none_when_store_is_missing() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("nonexistent.json");

        let result = format_discovered_patterns_section(&path);
        assert!(result.is_none(), "missing file must return None");
    }

    #[test]
    fn returns_section_containing_pattern_digest() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path().join("learn");

        record_discovered_error_patterns(
            &learn_dir,
            "compile:cargo",
            CARGO_E0425_LIB,
            "plan-1",
            "task-1",
        );

        let path = learn_dir.join("discovered-patterns.json");
        let section = format_discovered_patterns_section(&path)
            .expect("section must be Some when patterns exist");

        assert!(
            section.contains("Known error patterns from parallel tasks"),
            "section must contain the header"
        );
        assert!(
            section.contains("E0425"),
            "section must contain the error code from the digest"
        );
    }

    #[test]
    fn resolved_patterns_are_excluded_from_section() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("discovered-patterns.json");

        let now = "2026-01-01T00:00:00+00:00";
        let json = serde_json::json!({
            "patterns": [
                {
                    "key": "E0425::src/lib.rs",
                    "digest": "E0425: cannot find value `foo` [src/lib.rs]",
                    "gate": "compile:cargo",
                    "category": "unresolved_import",
                    "occurrences": 1,
                    "first_seen_at": now,
                    "last_seen_at": now,
                    "plan_ids": ["plan-1"],
                    "task_ids": ["task-1"],
                    "resolved": true,
                    "resolution": "fixed",
                    "suggestion": null
                },
                {
                    "key": "E0308::src/main.rs",
                    "digest": "E0308: mismatched types [src/main.rs]",
                    "gate": "compile:cargo",
                    "category": "type_mismatch",
                    "occurrences": 2,
                    "first_seen_at": now,
                    "last_seen_at": now,
                    "plan_ids": ["plan-1"],
                    "task_ids": ["task-2"],
                    "resolved": false,
                    "resolution": null,
                    "suggestion": null
                }
            ]
        });
        std::fs::write(&path, serde_json::to_string_pretty(&json).unwrap()).unwrap();

        let section = format_discovered_patterns_section(&path)
            .expect("section must be Some since one unresolved pattern exists");

        assert!(
            !section.contains("E0425"),
            "resolved pattern must not appear in section"
        );
        assert!(
            section.contains("E0308"),
            "unresolved pattern must appear in section"
        );
    }

    #[test]
    fn section_bounded_to_five_patterns() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path().join("learn");

        let gate_outputs: &[&str] = &[
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0400","explanation":null},"level":"error","spans":[{"file_name":"src/a.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0401","explanation":null},"level":"error","spans":[{"file_name":"src/b.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0402","explanation":null},"level":"error","spans":[{"file_name":"src/c.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0403","explanation":null},"level":"error","spans":[{"file_name":"src/d.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0404","explanation":null},"level":"error","spans":[{"file_name":"src/e.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0405","explanation":null},"level":"error","spans":[{"file_name":"src/f.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0406","explanation":null},"level":"error","spans":[{"file_name":"src/g.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
            r#"{"reason":"compiler-message","message":{"message":"err","code":{"code":"E0407","explanation":null},"level":"error","spans":[{"file_name":"src/h.rs","line_start":1,"column_start":1,"is_primary":true}],"children":[]}}"#,
        ];
        for (i, output) in gate_outputs.iter().enumerate() {
            record_discovered_error_patterns(
                &learn_dir,
                "compile:cargo",
                output,
                "plan-a",
                &format!("task-{i}"),
            );
        }

        let path = learn_dir.join("discovered-patterns.json");
        let section = format_discovered_patterns_section(&path)
            .expect("section must be Some for non-empty store");

        // Count numbered list items ("1. ", "2. ", ...): the function caps at 5.
        let entry_count = section
            .lines()
            .filter(|l| l.starts_with(|c: char| c.is_ascii_digit()))
            .count();
        assert!(
            entry_count <= 5,
            "section must contain at most 5 pattern entries, got {entry_count}"
        );
    }
}

// ─── Worktree lifecycle cleanup tests (E47-T06) ──────────────────────────────
//
// Unit tests verifying cleanup eligibility logic, TTL configuration, and that
// the worktree manager honours the age threshold from ResourcesConfig.
#[cfg(test)]
mod tests_worktree_lifecycle {
    use super::*;
    use roko_core::config::schema::ResourcesConfig;
    use tempfile::TempDir;

    // ── 1. Default TTL matches the compile-time constant ───────────────────

    #[test]
    fn worktree_manager_default_ttl_matches_constant() {
        let dir = TempDir::new().unwrap();
        // Both helpers must produce a manager with zero tracked worktrees.
        let mgr_default = default_runner_worktree_manager(dir.path());
        let mgr_explicit =
            default_runner_worktree_manager_with_ttl(dir.path(), RUNNER_WORKTREE_IDLE_TTL_SECS);
        assert_eq!(mgr_default.active_count(), 0);
        assert_eq!(mgr_explicit.active_count(), 0);
    }

    // ── 2. Config-driven TTL builds a valid manager ─────────────────────────

    #[test]
    fn worktree_manager_with_custom_ttl_is_empty_on_creation() {
        let dir = TempDir::new().unwrap();
        let custom_secs = 7200_u64; // 2 hours
        let mgr = default_runner_worktree_manager_with_ttl(dir.path(), custom_secs);
        assert_eq!(
            mgr.active_count(),
            0,
            "fresh manager must start with zero tracked worktrees"
        );
    }

    // ── 3. Default ResourcesConfig produces the expected 24-hour threshold ──

    #[test]
    fn resources_config_default_worktree_max_age_secs_is_24h() {
        let cfg = ResourcesConfig::default();
        assert_eq!(
            cfg.worktree_max_age_secs, 86400,
            "default worktree_max_age_secs must be 86400 (24 hours)"
        );
    }

    // ── 4. worktree_max_age_secs round-trips through TOML ───────────────────

    #[test]
    fn worktree_max_age_secs_parses_from_toml() {
        let toml = "[resources]\nworktree_max_age_secs = 3600\n";
        let cfg: roko_core::config::schema::RokoConfig =
            toml::from_str(toml).expect("toml must parse");
        assert_eq!(
            cfg.resources.worktree_max_age_secs, 3600,
            "custom worktree_max_age_secs must survive a TOML round-trip"
        );
    }

    // ── 5. Missing [resources] falls back to defaults (including max_age) ───

    #[test]
    fn missing_resources_section_yields_defaults() {
        let cfg: roko_core::config::schema::RokoConfig =
            toml::from_str("").expect("empty toml must parse");
        let res = &cfg.resources;
        assert!(
            res.worktree_cleanup_on_complete,
            "worktree_cleanup_on_complete must default to true"
        );
        assert!(
            res.worktree_cleanup_on_failure,
            "worktree_cleanup_on_failure must default to true"
        );
        assert_eq!(
            res.worktree_max_age_secs, 86400,
            "worktree_max_age_secs must default to 86400 when [resources] is absent"
        );
    }

    // ── 6. cleanup_orphan_worktrees is a no-op when directory is absent ─────

    #[tokio::test]
    async fn cleanup_orphan_worktrees_no_op_when_dir_absent() {
        let dir = TempDir::new().unwrap();
        let mgr = default_runner_worktree_manager(dir.path());
        // .roko/worktrees/ does not exist → must not panic or error
        cleanup_orphan_worktrees(dir.path(), &mgr).await;
    }

    // ── 7. Cleanup eligibility: success path ────────────────────────────────

    #[test]
    fn cleanup_eligible_success_respects_complete_flag() {
        let mut cfg_on = ResourcesConfig::default();
        cfg_on.worktree_cleanup_on_complete = true;
        cfg_on.worktree_cleanup_on_failure = false;

        let mut cfg_off = ResourcesConfig::default();
        cfg_off.worktree_cleanup_on_complete = false;
        cfg_off.worktree_cleanup_on_failure = true;

        assert!(
            worktree_cleanup_eligible(&cfg_on, true),
            "cleanup must be enabled when worktree_cleanup_on_complete=true and run succeeded"
        );
        assert!(
            !worktree_cleanup_eligible(&cfg_off, true),
            "cleanup must be suppressed when worktree_cleanup_on_complete=false"
        );
    }

    // ── 8. Cleanup eligibility: failure path ────────────────────────────────

    #[test]
    fn cleanup_eligible_failure_respects_failure_flag() {
        let mut cfg_on = ResourcesConfig::default();
        cfg_on.worktree_cleanup_on_complete = false;
        cfg_on.worktree_cleanup_on_failure = true;

        let mut cfg_off = ResourcesConfig::default();
        cfg_off.worktree_cleanup_on_complete = true;
        cfg_off.worktree_cleanup_on_failure = false;

        assert!(
            worktree_cleanup_eligible(&cfg_on, false),
            "cleanup must be enabled when worktree_cleanup_on_failure=true and run failed"
        );
        assert!(
            !worktree_cleanup_eligible(&cfg_off, false),
            "cleanup must be suppressed when worktree_cleanup_on_failure=false"
        );
    }
}

// ── Per-plan disk budget enforcement ─────────────────────────────────────────

/// Check whether the combined size of `.roko/` and `target/` directories under
/// `workdir` exceeds `max_mb`.
///
/// Returns `Ok(true)` when usage is within budget (or `max_mb == 0`, meaning
/// unlimited).  Returns `Ok(false)` when the budget is exceeded.  Any I/O
/// error during directory traversal is logged and treated as "within budget"
/// so that a transient read failure never blocks the plan.
async fn check_plan_disk_budget(workdir: &Path, max_mb: u64) -> Result<bool> {
    // 0 = unlimited — always within budget.
    if max_mb == 0 {
        return Ok(true);
    }

    let roko_dir = workdir.join(".roko");
    let target_dir = workdir.join("target");

    let mut total_mb: u64 = 0;

    if roko_dir.is_dir() {
        match roko_fs::gc::dir_size_mb(&roko_dir).await {
            Ok(mb) => total_mb = total_mb.saturating_add(mb),
            Err(e) => {
                warn!(
                    path = %roko_dir.display(),
                    error = %e,
                    "failed to measure .roko/ directory size — skipping budget check"
                );
                return Ok(true);
            }
        }
    }

    if target_dir.is_dir() {
        match roko_fs::gc::dir_size_mb(&target_dir).await {
            Ok(mb) => total_mb = total_mb.saturating_add(mb),
            Err(e) => {
                warn!(
                    path = %target_dir.display(),
                    error = %e,
                    "failed to measure target/ directory size — skipping budget check"
                );
                return Ok(true);
            }
        }
    }

    if total_mb > max_mb {
        warn!(
            total_mb,
            max_mb,
            roko_dir = %roko_dir.display(),
            target_dir = %target_dir.display(),
            "per-plan disk budget exceeded: {} MB used > {} MB limit",
            total_mb,
            max_mb,
        );
        Ok(false)
    } else {
        debug!(
            total_mb,
            max_mb,
            "per-plan disk budget check passed: {} MB used <= {} MB limit",
            total_mb,
            max_mb,
        );
        Ok(true)
    }
}

// ── Disk pre-check ───────────────────────────────────────────────────────────

/// Check disk space at `workdir` against the configured thresholds.
///
/// # Behaviour
///
/// | Level    | Condition                                   | Action                          |
/// |----------|---------------------------------------------|---------------------------------|
/// | Ok       | `free >= warn_disk_mb`                      | debug log; proceed              |
/// | Warning  | `min_free_disk_mb <= free < warn_disk_mb`   | `warn!`; proceed                |
/// | Critical | `free < min_free_disk_mb`                   | `Err` unless `force` is `true`  |
///
/// The check runs *after* the optional pre-run GC so that any space reclaimed
/// by GC is reflected in the measurement.
///
/// When `force` is `true` the check still measures and logs but never returns
/// `Err`.
fn disk_pre_check(
    workdir: &Path,
    resources: Option<&roko_core::config::ResourcesConfig>,
    force: bool,
) -> Result<()> {
    let defaults = roko_core::config::ResourcesConfig::default();
    let min_free_mb = resources
        .map(|r| r.min_free_disk_mb)
        .unwrap_or(defaults.min_free_disk_mb);
    let warn_mb = resources
        .map(|r| r.warn_disk_mb)
        .unwrap_or(defaults.warn_disk_mb);

    let monitor = roko_fs::DiskMonitor::new(min_free_mb, warn_mb);

    match monitor.check_pre_run(workdir) {
        Ok(()) => {}
        Err(disk_err) => {
            if force {
                warn!(
                    free_mb = disk_err.free_mb,
                    required_mb = disk_err.required_mb,
                    path = %workdir.display(),
                    "--force bypasses disk-space pre-check: {} MB free, {} MB required",
                    disk_err.free_mb,
                    disk_err.required_mb,
                );
            } else {
                return Err(anyhow::anyhow!(
                    "disk space check failed: {} MB available at {}, {} MB required\n\
                     Free up space or raise `resources.min_free_disk_mb` in roko.toml.\n\
                     To bypass this check (dangerous), pass `--force`.",
                    disk_err.free_mb,
                    workdir.display(),
                    disk_err.required_mb,
                ));
            }
        }
    }

    if let Some(disk_warning) = monitor.check_warning(workdir) {
        warn!(
            free_mb = disk_warning.free_mb,
            threshold_mb = disk_warning.threshold_mb,
            "low disk space warning: {} MB free, {} MB warn threshold",
            disk_warning.free_mb,
            disk_warning.threshold_mb,
        );
    } else {
        debug!(min_free_mb, warn_mb, "disk space pre-check passed");
    }

    Ok(())
}

#[cfg(test)]
mod disk_tests {
    use super::*;
    use std::path::PathBuf;

    fn workdir() -> PathBuf {
        std::env::temp_dir()
    }

    /// A threshold of 0 MB means "always pass regardless of free space".
    #[test]
    fn zero_threshold_always_passes() {
        // min=0, warn=0 — should never fail.
        assert!(
            disk_pre_check(&workdir(), Some(&cfg(0, 0)), false).is_ok(),
            "zero threshold must always pass without --force"
        );
    }

    /// force=true with zero threshold also passes (trivially).
    #[test]
    fn zero_threshold_with_force_passes() {
        assert!(
            disk_pre_check(&workdir(), Some(&cfg(0, 0)), true).is_ok(),
            "zero threshold with --force must pass"
        );
    }

    /// A threshold of u64::MAX is always unsatisfied, so without --force we
    /// must get an error and the message must mention the available MB, the
    /// required MB, and the --force flag.
    #[test]
    fn extreme_threshold_fails_without_force() {
        let result = disk_pre_check(&workdir(), Some(&cfg(u64::MAX, u64::MAX)), false);
        assert!(
            result.is_err(),
            "extreme threshold must fail without --force"
        );
        let msg = format!("{}", result.unwrap_err());
        assert!(
            msg.contains("MB available") || msg.contains("MB free") || msg.contains("disk space"),
            "error message must mention disk space: {msg}"
        );
        assert!(
            msg.contains("--force"),
            "error message must mention --force: {msg}"
        );
    }

    /// With --force, even an extreme threshold must not return Err.
    #[test]
    fn extreme_threshold_passes_with_force() {
        assert!(
            disk_pre_check(&workdir(), Some(&cfg(u64::MAX, u64::MAX)), true).is_ok(),
            "extreme threshold with --force must not return Err"
        );
    }

    /// min=0, warn=u64::MAX → in the warning band (check_warning fires) but
    /// check_pre_run passes. The function must return Ok.
    #[test]
    fn warning_band_passes_and_does_not_error() {
        assert!(
            disk_pre_check(&workdir(), Some(&cfg(0, u64::MAX)), false).is_ok(),
            "warning band must not return Err (only log a warning)"
        );
    }

    /// None config uses defaults (2048 MB / 5120 MB). On developer machines
    /// with ample disk this should pass; the test is skipped when the machine
    /// has less than 2 GB free to avoid false positives in CI.
    #[test]
    fn none_config_uses_defaults_and_passes_on_real_disk() {
        // Skip if the machine has less than the default minimum free space.
        let defaults = roko_core::config::ResourcesConfig::default();
        let free_mb = roko_fs::available_disk_mb(&workdir()).unwrap_or(u64::MAX);
        if free_mb < defaults.min_free_disk_mb {
            // Machine is constrained — skip rather than fail.
            return;
        }
        assert!(
            disk_pre_check(&workdir(), None, false).is_ok(),
            "default config must pass when machine has >= {} MB free",
            defaults.min_free_disk_mb
        );
    }

    /// With --force, every threshold (0, 1024, MAX) must never return Err.
    #[test]
    fn force_flag_never_returns_error() {
        for min in [0u64, 1024, u64::MAX] {
            assert!(
                disk_pre_check(&workdir(), Some(&cfg(min, u64::MAX)), true).is_ok(),
                "force=true must not return Err for min={min}"
            );
        }
    }

    fn cfg(min_free_disk_mb: u64, warn_disk_mb: u64) -> roko_core::config::ResourcesConfig {
        roko_core::config::ResourcesConfig {
            min_free_disk_mb,
            warn_disk_mb,
            ..roko_core::config::ResourcesConfig::default()
        }
    }
}

// ─── Per-plan disk budget tests (E47-T09) ─────────────────────────────────────
#[cfg(test)]
mod tests_plan_disk_budget {
    use super::*;
    use tempfile::TempDir;

    /// `max_mb = 0` means unlimited — always returns `Ok(true)`.
    #[tokio::test]
    async fn zero_max_is_unlimited() {
        let dir = TempDir::new().unwrap();
        let result = check_plan_disk_budget(dir.path(), 0).await;
        assert!(result.is_ok());
        assert!(result.unwrap(), "max_mb=0 must always be within budget");
    }

    /// An empty directory is always within any positive budget.
    #[tokio::test]
    async fn empty_workdir_within_budget() {
        let dir = TempDir::new().unwrap();
        let result = check_plan_disk_budget(dir.path(), 1024).await;
        assert!(result.is_ok());
        assert!(
            result.unwrap(),
            "empty workdir must be within a 1024 MB budget"
        );
    }

    /// When `.roko/` and `target/` exist but are small, the check passes.
    #[tokio::test]
    async fn small_dirs_within_budget() {
        let dir = TempDir::new().unwrap();
        // Create small .roko/ and target/ dirs with a file each.
        std::fs::create_dir(dir.path().join(".roko")).unwrap();
        std::fs::write(dir.path().join(".roko/test.json"), b"{}").unwrap();
        std::fs::create_dir(dir.path().join("target")).unwrap();
        std::fs::write(dir.path().join("target/test.bin"), b"data").unwrap();

        let result = check_plan_disk_budget(dir.path(), 100).await;
        assert!(result.is_ok());
        assert!(result.unwrap(), "tiny dirs must be within a 100 MB budget");
    }

    /// When the combined size exceeds the budget, the check returns `Ok(false)`.
    #[tokio::test]
    async fn large_dirs_exceed_budget() {
        let dir = TempDir::new().unwrap();
        std::fs::create_dir(dir.path().join(".roko")).unwrap();
        // Write a file larger than the budget.
        let data = vec![0u8; 2 * 1024 * 1024]; // 2 MB
        std::fs::write(dir.path().join(".roko/big.bin"), &data).unwrap();

        let result = check_plan_disk_budget(dir.path(), 1).await;
        assert!(result.is_ok());
        assert!(!result.unwrap(), "2 MB .roko/ must exceed a 1 MB budget");
    }

    /// When only `target/` exists and exceeds the budget, the check catches it.
    #[tokio::test]
    async fn target_only_exceeds_budget() {
        let dir = TempDir::new().unwrap();
        std::fs::create_dir(dir.path().join("target")).unwrap();
        let data = vec![0u8; 3 * 1024 * 1024]; // 3 MB
        std::fs::write(dir.path().join("target/artifacts.bin"), &data).unwrap();

        let result = check_plan_disk_budget(dir.path(), 2).await;
        assert!(result.is_ok());
        assert!(!result.unwrap(), "3 MB target/ must exceed a 2 MB budget");
    }

    /// When neither `.roko/` nor `target/` exist, usage is 0 — always within budget.
    #[tokio::test]
    async fn no_dirs_within_budget() {
        let dir = TempDir::new().unwrap();
        let result = check_plan_disk_budget(dir.path(), 1).await;
        assert!(result.is_ok());
        assert!(
            result.unwrap(),
            "no .roko/ or target/ means 0 MB usage — always within budget"
        );
    }

    /// The function never returns an error for a valid directory path.
    #[tokio::test]
    async fn always_returns_ok() {
        let dir = TempDir::new().unwrap();
        for max_mb in [0, 1, 100, 1024, u64::MAX] {
            let result = check_plan_disk_budget(dir.path(), max_mb).await;
            assert!(
                result.is_ok(),
                "check_plan_disk_budget must return Ok for max_mb={max_mb}"
            );
        }
    }
}

#[cfg(test)]
mod tests_reflect {
    //! E45-T04: Unit tests for the post-gate reflection loop with dedup and cost guard.

    use super::*;
    use roko_learn::post_gate_reflection::{PostGateReflectionStore, ReflectionGateOutcome};
    use tempfile::TempDir;

    /// Helper: call record_gate_failure_reflection with a fresh temp dir.
    fn record_once(
        gate: &str,
        output: &str,
        iteration: u32,
    ) -> (PostGateReflectionStore, f64, TempDir) {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path();
        let mut cost = 0.0_f64;
        record_gate_failure_reflection(
            learn_dir, gate, output, "plan-1", "task-1", iteration, &mut cost,
        );
        let store = PostGateReflectionStore::load(&learn_dir.join("post-gate-reflections.json"));
        (store, cost, dir)
    }

    #[test]
    fn reflect_records_one_entry_on_first_failure() {
        let (store, cost, _dir) =
            record_once("compile", "error[E0308]: type mismatch foo/bar.rs:10", 1);
        assert_eq!(store.records.len(), 1);
        let record = &store.records[0];
        assert_eq!(record.trigger_gate, "compile");
        assert_eq!(record.outcome, ReflectionGateOutcome::Failed);
        assert!(!record.proposed_lesson.is_empty());
        assert!(cost > 0.0, "nominal cost must be charged");
    }

    #[test]
    fn reflect_cost_guard_stops_recording_when_exceeded() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path();
        // Pre-load cost already at the guard limit.
        let mut cost = REFLECTION_COST_GUARD_USD;
        record_gate_failure_reflection(
            learn_dir,
            "compile",
            "error[E0308]: type mismatch foo/bar.rs:10",
            "plan-1",
            "task-1",
            1,
            &mut cost,
        );
        // Store must still be empty — guard tripped before recording.
        let store = PostGateReflectionStore::load(&learn_dir.join("post-gate-reflections.json"));
        assert_eq!(
            store.records.len(),
            0,
            "cost guard must prevent recording when budget is exhausted"
        );
        // Cost must not have increased.
        assert_eq!(cost, REFLECTION_COST_GUARD_USD);
    }

    #[test]
    fn reflect_dedup_skips_very_similar_error() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path();

        // A long enough output for the 60-char prefix overlap dedup logic.
        let long_output = "error[E0308]: expected `u32`, found `String` in \
            src/lib.rs:10:15 and many more details follow here so we have plenty of text";

        let mut cost = 0.0_f64;
        // First call: should record.
        record_gate_failure_reflection(
            learn_dir,
            "compile",
            long_output,
            "plan-1",
            "task-1",
            1,
            &mut cost,
        );
        let store_after_first =
            PostGateReflectionStore::load(&learn_dir.join("post-gate-reflections.json"));
        assert_eq!(store_after_first.records.len(), 1);

        // Second call with same output: cost must not exceed one observation
        // fee per call (dedup may or may not fire depending on classification).
        let cost_before_second = cost;
        record_gate_failure_reflection(
            learn_dir,
            "compile",
            long_output,
            "plan-1",
            "task-1",
            2,
            &mut cost,
        );
        assert!(
            cost <= cost_before_second + REFLECTION_COST_PER_OBSERVATION_USD + f64::EPSILON,
            "cost must not exceed one observation fee per call"
        );
    }

    #[test]
    fn reflect_missing_dir_is_handled_gracefully() {
        let dir = TempDir::new().unwrap();
        // Use a nested path that doesn't exist yet.
        let learn_dir = dir.path().join("nested").join("learn");
        let mut cost = 0.0_f64;
        // Must not panic.
        record_gate_failure_reflection(
            &learn_dir,
            "test",
            "FAILED: assertion failed at line 42",
            "plan-1",
            "task-1",
            1,
            &mut cost,
        );
        // Either recorded or not — just must not panic.
        // If the dir was created, we only verify no panic occurred.
        let _ = cost;
    }

    #[test]
    fn reflect_accumulates_cost_across_multiple_distinct_failures() {
        let dir = TempDir::new().unwrap();
        let learn_dir = dir.path();
        let mut cost = 0.0_f64;

        let errors = [
            "error[E0308]: first error at lib.rs:1",
            "error[E0277]: trait bound not satisfied at main.rs:5",
            "FAILED: test_foo panicked at tests/foo.rs:10",
        ];
        for (i, output) in errors.iter().enumerate() {
            record_gate_failure_reflection(
                learn_dir,
                "compile",
                output,
                "plan-1",
                &format!("task-{i}"),
                1,
                &mut cost,
            );
        }

        let store = PostGateReflectionStore::load(&learn_dir.join("post-gate-reflections.json"));
        assert!(
            !store.records.is_empty(),
            "at least one reflection must be recorded"
        );
        assert!(cost > 0.0, "cost must accumulate across observations");
    }
}

#[cfg(test)]
mod tests_post_plan_cleanup {
    //! E47-T11: Unit tests for post_plan_cleanup and CleanupSummary.

    use super::*;
    use roko_core::config::ResourcesConfig;
    use tempfile::TempDir;

    /// Helper: build a RokoLayout with ensure_dirs and return (TempDir, RokoLayout).
    async fn setup_layout() -> (TempDir, RokoLayout) {
        let tmp = TempDir::new().expect("tempdir");
        let layout = RokoLayout::for_project(tmp.path());
        layout.ensure_dirs().await.expect("ensure_dirs");
        (tmp, layout)
    }

    #[tokio::test]
    async fn pre_plan_maintenance_removes_worktree_target_before_gc() {
        let (tmp, layout) = setup_layout().await;
        let target = tmp
            .path()
            .join(".roko")
            .join("worktrees")
            .join("old-plan")
            .join("target");
        tokio::fs::create_dir_all(&target).await.unwrap();
        tokio::fs::write(target.join("artifact"), b"stale")
            .await
            .unwrap();

        let resources = ResourcesConfig {
            target_cleanup_enabled: true,
            target_max_age_days: 0,
            gc_on_plan_start: false,
            ..Default::default()
        };
        run_pre_plan_resource_maintenance(&layout, tmp.path(), Some(&resources)).await;

        assert!(
            !target.exists(),
            "pre-plan maintenance must clean canonical worktree targets"
        );
    }

    #[tokio::test]
    async fn pre_plan_maintenance_respects_disabled_target_cleanup() {
        let (tmp, layout) = setup_layout().await;
        let target = tmp
            .path()
            .join(".roko")
            .join("worktrees")
            .join("kept-plan")
            .join("target");
        tokio::fs::create_dir_all(&target).await.unwrap();

        let resources = ResourcesConfig {
            target_cleanup_enabled: false,
            target_max_age_days: 0,
            gc_on_plan_start: false,
            ..Default::default()
        };
        run_pre_plan_resource_maintenance(&layout, tmp.path(), Some(&resources)).await;

        assert!(
            target.exists(),
            "disabled target cleanup must preserve the worktree target"
        );
    }

    #[tokio::test]
    async fn between_task_cleanup_skips_non_cargo_worktree() {
        let tmp = TempDir::new().unwrap();
        let target = tmp.path().join("target");
        tokio::fs::create_dir_all(&target).await.unwrap();
        tokio::fs::write(target.join("artifact"), b"keep")
            .await
            .unwrap();

        clean_task_target_after_gate(Some(&ResourcesConfig::default()), Some(tmp.path())).await;

        assert!(
            target.exists(),
            "a non-Cargo task worktree must not invoke cargo clean"
        );
    }

    // ── CleanupSummary ──────────────────────────────────────────────────

    #[test]
    fn cleanup_summary_default_is_zero() {
        let s = CleanupSummary::default();
        assert_eq!(s.logs_rotated, 0);
        assert_eq!(s.gc_items_removed, 0);
        assert_eq!(s.gc_bytes_freed, 0);
        assert_eq!(s.target_dirs_removed, 0);
        assert_eq!(s.target_bytes_freed, 0);
        assert_eq!(s.worktrees_removed, 0);
        assert_eq!(s.errors, 0);
    }

    // ── post_plan_cleanup integration ───────────────────────────────────

    #[tokio::test]
    async fn cleanup_on_empty_layout_succeeds() {
        let (tmp, layout) = setup_layout().await;
        let workdir = tmp.path().to_path_buf();

        let wt_cfg = WorktreeConfig {
            repo_root: workdir.clone(),
            ..Default::default()
        };
        let worktrees = WorktreeManager::new(wt_cfg);

        let res = ResourcesConfig::default();
        let summary = post_plan_cleanup(&layout, &workdir, Some(&res), true, &worktrees).await;

        // Nothing to clean on a fresh layout.
        assert_eq!(summary.logs_rotated, 0);
        assert_eq!(summary.gc_items_removed, 0);
        assert_eq!(summary.target_dirs_removed, 0);
        assert_eq!(summary.errors, 0);
    }

    #[tokio::test]
    async fn cleanup_rotates_large_log_files() {
        let (tmp, layout) = setup_layout().await;
        let workdir = tmp.path().to_path_buf();

        // Write a non-empty episodes.jsonl; use max_mb=0 to force rotation.
        let episodes = layout.episodes_path();
        tokio::fs::write(&episodes, "{\"id\":1}\n{\"id\":2}\n")
            .await
            .unwrap();

        let wt_cfg = WorktreeConfig {
            repo_root: workdir.clone(),
            ..Default::default()
        };
        let worktrees = WorktreeManager::new(wt_cfg);

        let mut res = ResourcesConfig::default();
        res.log_rotation_max_mb = 0; // force rotation of any non-empty file
        res.gc_on_plan_end = false; // isolate log rotation test
        res.target_cleanup_enabled = false;

        let summary = post_plan_cleanup(&layout, &workdir, Some(&res), true, &worktrees).await;

        assert!(
            summary.logs_rotated > 0,
            "should rotate at least one log file"
        );
        // The live file should exist and be empty.
        let live = tokio::fs::read_to_string(&episodes).await.unwrap();
        assert!(
            live.is_empty(),
            "live episodes.jsonl should be empty after rotation"
        );
    }

    #[tokio::test]
    async fn cleanup_runs_gc_when_enabled() {
        let (tmp, layout) = setup_layout().await;
        let workdir = tmp.path().to_path_buf();

        // Write excess episodes (more than max_episodes=200 in FsRetentionPolicy default).
        let mut content = String::new();
        for i in 0..300 {
            content.push_str(&format!("{{\"id\":{i}}}\n"));
        }
        tokio::fs::write(layout.episodes_path(), &content)
            .await
            .unwrap();

        let wt_cfg = WorktreeConfig {
            repo_root: workdir.clone(),
            ..Default::default()
        };
        let worktrees = WorktreeManager::new(wt_cfg);

        let mut res = ResourcesConfig::default();
        res.gc_on_plan_end = true;
        res.target_cleanup_enabled = false;

        let summary = post_plan_cleanup(&layout, &workdir, Some(&res), true, &worktrees).await;

        // The GC engine should detect the excess episodes.
        assert!(
            summary.gc_items_removed > 0 || summary.gc_bytes_freed > 0 || summary.errors == 0, // even if nothing removed, no errors
            "GC should run without errors"
        );
    }

    #[tokio::test]
    async fn cleanup_skips_gc_when_disabled() {
        let (tmp, layout) = setup_layout().await;
        let workdir = tmp.path().to_path_buf();

        let wt_cfg = WorktreeConfig {
            repo_root: workdir.clone(),
            ..Default::default()
        };
        let worktrees = WorktreeManager::new(wt_cfg);

        let mut res = ResourcesConfig::default();
        res.gc_on_plan_end = false;
        res.target_cleanup_enabled = false;

        let summary = post_plan_cleanup(&layout, &workdir, Some(&res), true, &worktrees).await;

        assert_eq!(summary.gc_items_removed, 0);
        assert_eq!(summary.gc_bytes_freed, 0);
    }

    #[tokio::test]
    async fn cleanup_skips_target_when_disabled() {
        let (tmp, layout) = setup_layout().await;
        let workdir = tmp.path().to_path_buf();

        // Create a target/ directory to verify it is NOT cleaned.
        let target_dir = workdir.join("some-worktree").join("target");
        tokio::fs::create_dir_all(&target_dir).await.unwrap();
        tokio::fs::write(target_dir.join("artifact.rlib"), b"data")
            .await
            .unwrap();

        let wt_cfg = WorktreeConfig {
            repo_root: workdir.clone(),
            ..Default::default()
        };
        let worktrees = WorktreeManager::new(wt_cfg);

        let mut res = ResourcesConfig::default();
        res.gc_on_plan_end = false;
        res.target_cleanup_enabled = false;

        let summary = post_plan_cleanup(&layout, &workdir, Some(&res), true, &worktrees).await;

        assert_eq!(summary.target_dirs_removed, 0);
        // The target dir should still exist.
        assert!(
            target_dir.exists(),
            "target/ should not be removed when disabled"
        );
    }

    #[tokio::test]
    async fn cleanup_with_none_resources_uses_defaults() {
        let (tmp, layout) = setup_layout().await;
        let workdir = tmp.path().to_path_buf();

        let wt_cfg = WorktreeConfig {
            repo_root: workdir.clone(),
            ..Default::default()
        };
        let worktrees = WorktreeManager::new(wt_cfg);

        // Passing None for resources should use defaults and not panic.
        let summary = post_plan_cleanup(&layout, &workdir, None, true, &worktrees).await;

        assert_eq!(
            summary.errors, 0,
            "cleanup with default config should not error"
        );
    }

    // ── worktree_cleanup_eligible ───────────────────────────────────────

    #[test]
    fn worktree_cleanup_on_success_respects_flag() {
        let mut res = ResourcesConfig::default();
        res.worktree_cleanup_on_complete = true;
        assert!(worktree_cleanup_eligible(&res, true));

        res.worktree_cleanup_on_complete = false;
        assert!(!worktree_cleanup_eligible(&res, true));
    }

    #[test]
    fn worktree_cleanup_on_failure_respects_flag() {
        let mut res = ResourcesConfig::default();
        res.worktree_cleanup_on_failure = true;
        assert!(worktree_cleanup_eligible(&res, false));

        res.worktree_cleanup_on_failure = false;
        assert!(!worktree_cleanup_eligible(&res, false));
    }

    // ── auto_cleanup_on_complete config field ───────────────────────────

    #[test]
    fn auto_cleanup_defaults_to_true() {
        let res = ResourcesConfig::default();
        assert!(
            res.auto_cleanup_on_complete,
            "auto_cleanup_on_complete should default to true"
        );
    }

    #[test]
    fn auto_cleanup_deserializes_from_toml() {
        let toml_str = r#"
            auto_cleanup_on_complete = false
        "#;
        let res: ResourcesConfig = toml::from_str(toml_str).unwrap();
        assert!(
            !res.auto_cleanup_on_complete,
            "should deserialize false from TOML"
        );
    }
}

#[cfg(test)]
mod tests_disk_budget_tracker {
    use super::super::conductor_adapter::ConductorRing;
    use super::*;
    use tempfile::TempDir;

    fn tracker(min_free_disk_mb: u64, per_plan_disk_budget_mb: Option<u64>) -> DiskBudgetTracker {
        DiskBudgetTracker::new(&roko_core::config::ResourcesConfig {
            min_free_disk_mb,
            per_plan_disk_budget_mb,
            ..Default::default()
        })
    }

    #[test]
    fn disk_budget_tracker_defaults_to_conservative_three_gb_growth() {
        assert_eq!(tracker(0, None).next_estimate_mb(), 3 * 1024);
    }

    #[test]
    fn disk_budget_tracker_serializes_under_pressure_and_restores_parallelism() {
        let mut tracker = tracker(2_000, None);
        tracker.worktrees.insert(
            "active".into(),
            WorktreeDiskEstimate {
                plan_id: Some("plan-a".into()),
                attempt_key: Some("p:t:1".into()),
                baseline_mb: 0,
                actual_growth_mb: 0,
                estimated_growth_mb: DEFAULT_WORKTREE_GROWTH_MB,
                finalized: false,
            },
        );

        let pressured = tracker.admission_for("plan-a", 7_000, 1);
        assert!(pressured.pressure);
        assert!(pressured.defer_for_serialization);
        let settled = tracker.admission_for("plan-a", 7_000, 0);
        assert!(settled.pressure);
        assert!(!settled.defer_for_serialization);
        let recovered = tracker.admission_for("plan-a", 20_000, 2);
        assert!(!recovered.pressure);
        assert!(!recovered.defer_for_serialization);
    }

    #[test]
    fn disk_budget_tracker_scopes_configured_budget_across_two_plans() {
        let mut tracker = tracker(0, Some(6_000));
        tracker.worktrees.insert(
            "completed".into(),
            WorktreeDiskEstimate {
                plan_id: Some("plan-a".into()),
                attempt_key: None,
                baseline_mb: 0,
                actual_growth_mb: DEFAULT_WORKTREE_GROWTH_MB,
                estimated_growth_mb: DEFAULT_WORKTREE_GROWTH_MB,
                finalized: true,
            },
        );
        tracker.worktrees.insert(
            "other-plan".into(),
            WorktreeDiskEstimate {
                plan_id: Some("plan-b".into()),
                attempt_key: None,
                baseline_mb: 0,
                actual_growth_mb: 0,
                estimated_growth_mb: 5_000,
                finalized: false,
            },
        );
        let plan_a = tracker.admission_for("plan-a", 100_000, 1);
        assert_eq!(plan_a.remaining_mb, 6_000 - DEFAULT_WORKTREE_GROWTH_MB);
        assert!(plan_a.defer_for_serialization);
        let plan_b = tracker.admission_for("plan-b", 100_000, 1);
        assert_eq!(plan_b.remaining_mb, 1_000);
        let globally_constrained = tracker.admission_for("plan-a", 7_000, 1);
        assert_eq!(globally_constrained.remaining_mb, 2_000);
    }

    #[tokio::test]
    async fn disk_budget_tracker_attach_binds_recovered_entry_without_resetting_baseline() {
        let worktrees = WorktreeManager::from_snapshot(
            WorktreeConfig::default(),
            crate::orchestrator::WorktreeSnapshot {
                handles: vec![crate::orchestrator::WorktreeHandle {
                    id: crate::orchestrator::worktree::format_attempt_worktree_id(
                        "plan-a", "task-a", 1,
                    ),
                    path: PathBuf::from("/nonexistent/recovered-worktree"),
                    branch: "roko/attempt/recovered".into(),
                    created_at_ms: 0,
                    last_active_ms: 0,
                }],
                max_live: None,
                idle_ttl_ms: 1,
                timestamp_ms: 0,
            },
        )
        .unwrap();
        let attempt = TaskAttemptRef::new("plan-a", "task-a", 1);
        let mut tracker = tracker(0, None);
        tracker.refresh(&worktrees, &HashSet::new()).await;
        let id = worktrees.get_attempt("plan-a", "task-a", 1).unwrap().id;
        let baseline = tracker.worktrees[&id].baseline_mb;

        tracker.track_attempt(&attempt, &worktrees).await;

        let attached = &tracker.worktrees[&id];
        assert_eq!(attached.plan_id.as_deref(), Some("plan-a"));
        assert_eq!(
            attached.attempt_key.as_deref(),
            Some(attempt.key().as_str())
        );
        assert_eq!(attached.baseline_mb, baseline);
    }

    fn git(workdir: &Path, args: &[&str]) {
        let output = std::process::Command::new("git")
            .args(args)
            .current_dir(workdir)
            .output()
            .unwrap();
        assert!(output.status.success(), "git {args:?} failed: {output:?}");
    }

    #[tokio::test]
    async fn worktree_count_metric_tracks_create_attach_parallel_remove_and_reclaim() {
        let repo = TempDir::new().unwrap();
        git(repo.path(), &["init"]);
        git(
            repo.path(),
            &["config", "user.email", "roko@example.invalid"],
        );
        git(repo.path(), &["config", "user.name", "Roko Test"]);
        std::fs::write(repo.path().join("README.md"), "fixture\n").unwrap();
        git(repo.path(), &["add", "."]);
        git(repo.path(), &["commit", "-m", "initial"]);

        let worktree_config = WorktreeConfig {
            repo_root: repo.path().to_path_buf(),
            base_branch: "HEAD".into(),
            worktrees_root: repo.path().join(".roko/worktrees"),
            max_live: None,
            idle_ttl: Duration::from_millis(1),
        };
        let worktrees = WorktreeManager::new(worktree_config.clone());
        let ring = ConductorRing::with_capacity(16);
        let config = RunConfig {
            conductor_ring: Some(ring.clone()),
            ..Default::default()
        };
        let first = TaskAttemptRef::new("plan", "first", 1);
        let second = TaskAttemptRef::new("plan", "second", 1);

        publish_worktree_count(&config, &worktrees);
        ensure_attempt_workdir(&worktrees, &first).await.unwrap();
        publish_worktree_count(&config, &worktrees);
        ensure_attempt_workdir(&worktrees, &first).await.unwrap();
        publish_worktree_count(&config, &worktrees);
        ensure_attempt_workdir(&worktrees, &second).await.unwrap();
        publish_worktree_count(&config, &worktrees);
        let second_handle = worktrees.get_attempt("plan", "second", 1).unwrap();
        let after_remove = WorktreeManager::from_snapshot(
            worktree_config.clone(),
            crate::orchestrator::WorktreeSnapshot {
                handles: vec![second_handle],
                max_live: None,
                idle_ttl_ms: 1,
                timestamp_ms: 0,
            },
        )
        .unwrap();
        publish_worktree_count(&config, &after_remove);
        let after_reclaim = WorktreeManager::from_snapshot(
            worktree_config,
            crate::orchestrator::WorktreeSnapshot {
                handles: Vec::new(),
                max_live: None,
                idle_ttl_ms: 1,
                timestamp_ms: 0,
            },
        )
        .unwrap();
        publish_worktree_count(&config, &after_reclaim);

        let signals = ring.snapshot();
        assert_eq!(
            signals
                .iter()
                .map(|signal| {
                    assert_eq!(signal.kind, Kind::Metric);
                    assert_eq!(signal.tag("name"), Some("worktree_count"));
                    signal.tag("value").unwrap().parse::<usize>().unwrap()
                })
                .collect::<Vec<_>>(),
            vec![0, 1, 1, 2, 1, 0]
        );
    }

    #[tokio::test]
    async fn stale_reflex_replay_cleanup_preserves_live_lease_then_reclaims_dirty_checkout() {
        let repo = TempDir::new().expect("temporary replay repository");
        git(repo.path(), &["init"]);
        git(
            repo.path(),
            &["config", "user.email", "roko@example.invalid"],
        );
        git(repo.path(), &["config", "user.name", "Roko Test"]);
        std::fs::write(repo.path().join("README.md"), "fixture\n").expect("write replay fixture");
        git(repo.path(), &["add", "."]);
        git(repo.path(), &["commit", "-m", "initial"]);

        let manager = WorktreeManager::new(WorktreeConfig {
            repo_root: repo.path().to_path_buf(),
            base_branch: "HEAD".into(),
            worktrees_root: repo.path().join(".roko/worktrees"),
            max_live: None,
            idle_ttl: Duration::from_secs(60),
        });
        let id = "reflex-fedcba9876543210fedcba9876543210";
        let replay = manager
            .create(id, &format!("roko/reflex-replay/{id}"))
            .await
            .expect("create stale replay fixture");
        std::fs::write(replay.path.join("dirty.txt"), "replayed change\n")
            .expect("write dirty replay delta");
        let live_lease = acquire_reflex_replay_lease(repo.path(), id).expect("live replay lease");

        cleanup_stale_reflex_replay_branches(repo.path());
        assert!(
            replay.path.exists(),
            "a live replay lease must be preserved"
        );

        drop(live_lease);
        cleanup_stale_reflex_replay_branches(repo.path());
        assert!(!replay.path.exists(), "stale dirty replay must be removed");
        let branch = std::process::Command::new("git")
            .args([
                "show-ref",
                "--verify",
                &format!("refs/heads/{}", replay.branch),
            ])
            .current_dir(repo.path())
            .output()
            .expect("inspect stale replay branch");
        assert!(!branch.status.success(), "stale replay ref must be removed");
    }
}
